SELECT LOG_ID, FIRE_INSTANCE_ID, JOB_NAME, JOB_GROUP, TRIGGER_NAME, TRIGGER_GROUP, SCHEDULED_FIRE_TIME, ACTUAL_FIRE_TIME, FINISHED_AT, RUN_MILLIS, STATUS, EXCEPTION_MESSAGE, CREATED_AT FROM SCHED_EXEC_LOG WHERE 1=1
AND JOB_NAME LIKE '%' || #{jobName} || '%'
AND JOB_GROUP LIKE '%' || #{jobGroup} || '%'
AND STATUS = #{status}
AND ACTUAL_FIRE_TIME >= #{startDate}
AND ACTUAL_FIRE_TIME < #{endDateExclusive}
ORDER BY CREATED_AT DESC, LOG_ID DESC OFFSET #{offset} ROWS FETCH NEXT #{size} ROWS ONLY

SELECT COUNT(*)
FROM SCHED_EXEC_LOG
WHERE 1 = 1

    AND JOB_NAME LIKE '%' || #{jobName} || '%'


    AND JOB_GROUP LIKE '%' || #{jobGroup} || '%'


    AND STATUS = #{status}


    AND ACTUAL_FIRE_TIME  >=  #{startDate}


    AND ACTUAL_FIRE_TIME  <  #{endDateExclusive}
